CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_min_railway_id integer;
BEGIN
    SELECT MIN("Railway_ID")
    INTO v_min_railway_id
    FROM "railway_manage"
    WHERE "From_Year" = arg5;

    IF v_min_railway_id IS NOT NULL AND arg3 > 3 THEN
        UPDATE "railway"
        SET "Built" = arg3::text
        WHERE "Railway_ID" = arg6;

        CALL sp_part2(arg5, v_min_railway_id);
    ELSE
        CALL sp_part2(arg5, COALESCE(v_min_railway_id, arg6));

        IF arg3 <= 3 THEN
            DELETE FROM "railway_manage"
            WHERE "Manager_ID" = arg4
              AND "Railway_ID" < arg6;
        ELSE
            DELETE FROM "railway_manage"
            WHERE "Railway_ID" = arg6
              AND "From_Year" = arg5;
        END IF;
    END IF;

    IF arg2 IS NOT NULL THEN
        UPDATE "manager"
        SET "Country" = 'archive_' || "Country"
        WHERE "Manager_ID" = arg4
          AND "Working_year_starts" = arg2
          AND "Country" IS NOT NULL
          AND LEFT("Country", char_length('archive_')) <> 'archive_';
    END IF;

    CALL sp_part1(arg1, arg2, arg3, arg4, arg5, arg6);
END;
$$;

